/usr/bin/bash -lc 'TASK_TS=/home/zhihao/deveco/command-line-tools/codelinter/linter/arkPerfCheck/node_modules/arkanalyzer/node_modules/ohos-typescript; node - "$TASK_TS" <<'"'NODE'
const fs = require('fs');
const path = require('path');
const ts = require(process.argv[2]);
const roots = ['/workspace/YFree','/workspace/entry'];
let failed = false;
for (const root of roots) {
  function walk(dir) {
    for (const name of fs.readdirSync(dir)) {
      const file = path.join(dir, name);
      const stat = fs.statSync(file);
      if (stat.isDirectory()) walk(file);
      else if (/\\.(ets|ts)"'$/.test(name)) {
        const source = fs.readFileSync(file, '"'utf8');
        const sf = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
        if (sf.parseDiagnostics.length) {
          failed = true;
          console.log(file, sf.parseDiagnostics.map(d => d.messageText));
        }
      }
    }
  }
  walk(root);
}
if ("'!failed) console.log('"'ArkTS/TypeScript parse diagnostics: none');
process.exitCode = failed ? 1 : 0;
NODE"

