/usr/bin/bash -lc "node - <<'NODE'
const fs=require('fs');
const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8'));
const report=JSON.parse(fs.readFileSync('.exp_agent/round_completion_01.json','utf8'));
const expected=new Map();
for (const f of findings) { const k="'`${f.rule}|${f.relative_path}`; (expected.get(k)||expected.set(k,[]).get(k)).push(`${f.line}:${f.column}`); }
const actual=new Map();
for (const e of report.entity_repairs) actual.set(`${e.rule}|${e.relative_path}`, (e.locations||[]).map(x=>`${x.line}:${x.column}`));
let ok=report.entity_repairs.every(e=>Array.isArray(e.entities)&&e.entities.length&&Array.isArray(e.invariants)&&e.invariants.length&&Array.isArray(e.evidence)&&e.evidence.length&&e.transformation&&e.status==='"'repaired');
for (const [k,v] of expected) { if (JSON.stringify(v)"'!==JSON.stringify(actual.get(k)||[])) { ok=false; console.log('"'location mismatch:',k); } }
console.log(JSON.stringify({frozen_locations:findings.length,frozen_groups:expected.size,reported_groups:actual.size,required_fields_valid:ok}));
process.exitCode=ok&&actual.size===expected.size?0:1;
